#define SIZE 5

int items[SIZE], front = -1, rear = -1;

int isFull() { return (front == (rear + 1) % SIZE); }
int isEmpty() { return front == -1; }

void enqueue(int val) {
    if (isFull()) return;
    if (front == -1) front = 0;
    rear = (rear + 1) % SIZE;
    items[rear] = val;
}

int dequeue() {
    if (isEmpty()) return -1;
    int val = items[front];
    if (front == rear) { front = rear = -1; }
    else { front = (front + 1) % SIZE; }
    return val;
}

