#include <stdio.h>
#define MAX 100

typedef struct {
    int data[MAX];
    int top;
} Stack;

void init(Stack* s) { s->top = -1; }
int isFull(Stack* s) { return s->top == MAX - 1; }
int isEmpty(Stack* s) { return s->top == -1; }
void push(Stack* s, int val) {
    if (!isFull(s)) s->data[++(s->top)] = val;
}
int pop(Stack* s) {
    return isEmpty(s) ? -1 : s->data[(s->top)--];
}

