struct Edge { int u, v, w; };

struct DSU {
    std::vector<int> parent;
    DSU(int n) : parent(n) { for (int i = 0; i < n; i++) parent[i] = i; }
    int find(int i) { return (parent[i] == i) ? i : (parent[i] = find(parent[i])); }
    void unite(int i, int j) { parent[find(i)] = find(j); }
};

int main() {
    int V = 4;
    std::vector<Edge> edges = {{0, 1, 10}, {0, 2, 6}, {0, 3, 5}, {1, 3, 15}, {2, 3, 4}};
    std::sort(edges.begin(), edges.end(), [](Edge a, Edge b) { return a.w < b.w; });
    DSU dsu(V);
    int mst_weight = 0;
    for (auto& e : edges) {
        if (dsu.find(e.u) != dsu.find(e.v)) {
            dsu.unite(e.u, e.v);
            mst_weight += e.w;
        }
    }
    std::cout << "MST Weight: " << mst_weight << "\n";
    return 0;
}

#include <iostream>
#include <unordered_map>
#include <list>

class LRUCache {
    int capacity;
    std::list<std::pair<int, int>> items;
    std::unordered_map<int, std::list<std::pair<int, int>>::iterator> map;
public:
    LRUCache(int cap) : capacity(cap) {}
    int get(int key) {
        if (map.find(key) == map.end()) return -1;
        items.splice(items.begin(), items, map[key]);
        return map[key]->second;
    }
    void put(int key, int val) {
        if (map.find(key) != map.end()) {
            items.splice(items.begin(), items, map[key]);
            map[key]->second = val;
            return;
        }
        if (items.size() == capacity) {
            map.erase(items.back().first);
            items.pop_back();
        }
        items.emplace_front(key, val);
        map[key] = items.begin();
    }
};

int main() {
    LRUCache cache(2);
    cache.put(1, 10);
    cache.put(2, 20);
    std::cout << "Get 1: " << cache.get(1) << "\n";
    cache.put(3, 30); // evicts key 2
    std::cout << "Get 2: " << cache.get(2) << "\n";
    return 0;
}

