def simulate_dfa(string):
    # DFA states: q0 (start), q1 (seen 0), q2 (accepted, seen 01)
    state = 'q0'
    transitions = {
        'q0': {'0': 'q1', '1': 'q0'},
        'q1': {'0': 'q1', '1': 'q2'},
        'q2': {'0': 'q1', '1': 'q0'}
    }
    for char in string:
        if char not in ('0', '1'): return False
        state = transitions[state][char]
    return state == 'q2'

print("DFA accepts 1101:", simulate_dfa("1101"))
print("DFA accepts 1100:", simulate_dfa("1100"))

def fcfs(processes, bt):
    n = len(processes)
    wt = [0] * n
    tat = [0] * n
    for i in range(1, n):
        wt[i] = wt[i - 1] + bt[i - 1]
    for i in range(n):
        tat[i] = wt[i] + bt[i]
    print("Process\tBurst Time\tWaiting Time\tTurnaround Time")
    for i in range(n):
        print(f"{processes[i]}\t{bt[i]}\t\t{wt[i]}\t\t{tat[i]}")

