def lru_page_replacement(pages, capacity):
    memory = []
    faults = 0
    for page in pages:
        if page not in memory:
            if len(memory) == capacity:
                memory.pop(0) # Evict LRU
            memory.append(page)
            faults += 1
        else:
            memory.remove(page)
            memory.append(page) # Update usage
    return faults

